//! 命令表：`\alpha`、`\sum`、`\to` 这类 LaTeX 命令对应的字符和类别。

use super::{Class, Font};

/// 命令表里一项的类型。
#[derive(Clone, Copy)]
pub(super) enum Kind {
    /// 普通符号（类别、字体）。
    Sym(Class, Font),
    /// 放大的运算符（`\sum`）；上下限默认放在正上下方时为 `true`（积分为 `false`）。
    BigOp(bool),
    /// 函数名（`\sin`、`\lim`）；上下限默认放在正上下方时为 `true`。
    Func(bool),
}

/// 返回命令 `name` 对应的字符和类别；表里没有该命令时返回 `None`。
pub(super) fn lookup(name: &str) -> Option<(&'static str, Kind)> {
    use Class::{Bin, Close, Open, Ord, Punct, Rel};
    use Font::{Italic, Roman};
    let sym = |class| Kind::Sym(class, Roman);
    let found = match name {
        // 希腊字母：小写斜体，大写正体（LaTeX 的惯例）。
        "alpha" => ("α", Kind::Sym(Ord, Italic)),
        "beta" => ("β", Kind::Sym(Ord, Italic)),
        "gamma" => ("γ", Kind::Sym(Ord, Italic)),
        "delta" => ("δ", Kind::Sym(Ord, Italic)),
        "epsilon" => ("ϵ", Kind::Sym(Ord, Italic)),
        "varepsilon" => ("ε", Kind::Sym(Ord, Italic)),
        "zeta" => ("ζ", Kind::Sym(Ord, Italic)),
        "eta" => ("η", Kind::Sym(Ord, Italic)),
        "theta" => ("θ", Kind::Sym(Ord, Italic)),
        "vartheta" => ("ϑ", Kind::Sym(Ord, Italic)),
        "iota" => ("ι", Kind::Sym(Ord, Italic)),
        "kappa" => ("κ", Kind::Sym(Ord, Italic)),
        "lambda" => ("λ", Kind::Sym(Ord, Italic)),
        "mu" => ("μ", Kind::Sym(Ord, Italic)),
        "nu" => ("ν", Kind::Sym(Ord, Italic)),
        "xi" => ("ξ", Kind::Sym(Ord, Italic)),
        "omicron" => ("ο", Kind::Sym(Ord, Italic)),
        "pi" => ("π", Kind::Sym(Ord, Italic)),
        "varpi" => ("ϖ", Kind::Sym(Ord, Italic)),
        "rho" => ("ρ", Kind::Sym(Ord, Italic)),
        "varrho" => ("ϱ", Kind::Sym(Ord, Italic)),
        "sigma" => ("σ", Kind::Sym(Ord, Italic)),
        "varsigma" => ("ς", Kind::Sym(Ord, Italic)),
        "tau" => ("τ", Kind::Sym(Ord, Italic)),
        "upsilon" => ("υ", Kind::Sym(Ord, Italic)),
        "phi" => ("ϕ", Kind::Sym(Ord, Italic)),
        "varphi" => ("φ", Kind::Sym(Ord, Italic)),
        "chi" => ("χ", Kind::Sym(Ord, Italic)),
        "psi" => ("ψ", Kind::Sym(Ord, Italic)),
        "omega" => ("ω", Kind::Sym(Ord, Italic)),
        "Gamma" => ("Γ", sym(Ord)),
        "Delta" => ("Δ", sym(Ord)),
        "Theta" => ("Θ", sym(Ord)),
        "Lambda" => ("Λ", sym(Ord)),
        "Xi" => ("Ξ", sym(Ord)),
        "Pi" => ("Π", sym(Ord)),
        "Sigma" => ("Σ", sym(Ord)),
        "Upsilon" => ("Υ", sym(Ord)),
        "Phi" => ("Φ", sym(Ord)),
        "Psi" => ("Ψ", sym(Ord)),
        "Omega" => ("Ω", sym(Ord)),
        // 普通符号。
        "infty" => ("∞", sym(Ord)),
        "partial" => ("∂", sym(Ord)),
        "nabla" => ("∇", sym(Ord)),
        "forall" => ("∀", sym(Ord)),
        "exists" => ("∃", sym(Ord)),
        "nexists" => ("∄", sym(Ord)),
        "emptyset" | "varnothing" => ("∅", sym(Ord)),
        "hbar" | "hslash" => ("ℏ", sym(Ord)),
        "ell" => ("ℓ", sym(Ord)),
        "Re" => ("ℜ", sym(Ord)),
        "Im" => ("ℑ", sym(Ord)),
        "aleph" => ("ℵ", sym(Ord)),
        "wp" => ("℘", sym(Ord)),
        "angle" => ("∠", sym(Ord)),
        "triangle" => ("△", sym(Ord)),
        "neg" | "lnot" => ("¬", sym(Ord)),
        "top" => ("⊤", sym(Ord)),
        "bot" => ("⊥", sym(Ord)),
        "prime" => ("′", sym(Ord)),
        "degree" | "circ" => ("∘", sym(Bin)),
        "ldots" | "dots" | "dotso" | "dotsc" => ("…", sym(Ord)),
        "cdots" | "dotsb" | "dotsm" | "dotsi" => ("⋯", sym(Ord)),
        "vdots" => ("⋮", sym(Ord)),
        "ddots" => ("⋱", sym(Ord)),
        "%" => ("%", sym(Ord)),
        "$" => ("$", sym(Ord)),
        "#" => ("#", sym(Ord)),
        "&" => ("&", sym(Ord)),
        "_" => ("_", sym(Ord)),
        "{" | "lbrace" => ("{", sym(Open)),
        "}" | "rbrace" => ("}", sym(Close)),
        "|" | "Vert" => ("‖", sym(Ord)),
        "vert" | "mid" => ("∣", sym(Rel)),
        "backslash" | "setminus" => ("∖", sym(Bin)),
        "langle" => ("⟨", sym(Open)),
        "rangle" => ("⟩", sym(Close)),
        "lfloor" => ("⌊", sym(Open)),
        "rfloor" => ("⌋", sym(Close)),
        "lceil" => ("⌈", sym(Open)),
        "rceil" => ("⌉", sym(Close)),
        "checkmark" => ("✓", sym(Ord)),
        "star" => ("⋆", sym(Bin)),
        "dagger" => ("†", sym(Bin)),
        "ddagger" => ("‡", sym(Bin)),
        "S" => ("§", sym(Ord)),
        "colon" => (":", sym(Punct)),
        // 二元运算。
        "pm" => ("±", sym(Bin)),
        "mp" => ("∓", sym(Bin)),
        "times" => ("×", sym(Bin)),
        "div" => ("÷", sym(Bin)),
        "cdot" | "centerdot" => ("⋅", sym(Bin)),
        "ast" => ("∗", sym(Bin)),
        "bullet" => ("∙", sym(Bin)),
        "oplus" => ("⊕", sym(Bin)),
        "ominus" => ("⊖", sym(Bin)),
        "otimes" => ("⊗", sym(Bin)),
        "oslash" => ("⊘", sym(Bin)),
        "odot" => ("⊙", sym(Bin)),
        "cup" => ("∪", sym(Bin)),
        "cap" => ("∩", sym(Bin)),
        "sqcup" => ("⊔", sym(Bin)),
        "sqcap" => ("⊓", sym(Bin)),
        "vee" | "lor" => ("∨", sym(Bin)),
        "wedge" | "land" => ("∧", sym(Bin)),
        "uplus" => ("⊎", sym(Bin)),
        "wr" => ("≀", sym(Bin)),
        "diamond" => ("⋄", sym(Bin)),
        "bigtriangleup" => ("△", sym(Bin)),
        "bigtriangledown" => ("▽", sym(Bin)),
        // 关系。
        "le" | "leq" => ("≤", sym(Rel)),
        "ge" | "geq" => ("≥", sym(Rel)),
        "leqslant" => ("⩽", sym(Rel)),
        "geqslant" => ("⩾", sym(Rel)),
        "ne" | "neq" => ("≠", sym(Rel)),
        "ll" => ("≪", sym(Rel)),
        "gg" => ("≫", sym(Rel)),
        "approx" => ("≈", sym(Rel)),
        "sim" => ("∼", sym(Rel)),
        "simeq" => ("≃", sym(Rel)),
        "cong" => ("≅", sym(Rel)),
        "equiv" => ("≡", sym(Rel)),
        "propto" => ("∝", sym(Rel)),
        "doteq" => ("≐", sym(Rel)),
        "prec" => ("≺", sym(Rel)),
        "succ" => ("≻", sym(Rel)),
        "preceq" => ("⪯", sym(Rel)),
        "succeq" => ("⪰", sym(Rel)),
        "in" => ("∈", sym(Rel)),
        "notin" => ("∉", sym(Rel)),
        "ni" | "owns" => ("∋", sym(Rel)),
        "subset" => ("⊂", sym(Rel)),
        "supset" => ("⊃", sym(Rel)),
        "subseteq" => ("⊆", sym(Rel)),
        "supseteq" => ("⊇", sym(Rel)),
        "subsetneq" => ("⊊", sym(Rel)),
        "supsetneq" => ("⊋", sym(Rel)),
        "sqsubseteq" => ("⊑", sym(Rel)),
        "sqsupseteq" => ("⊒", sym(Rel)),
        "parallel" => ("∥", sym(Rel)),
        "nparallel" => ("∦", sym(Rel)),
        "perp" => ("⊥", sym(Rel)),
        "vdash" => ("⊢", sym(Rel)),
        "dashv" => ("⊣", sym(Rel)),
        "models" => ("⊨", sym(Rel)),
        "asymp" => ("≍", sym(Rel)),
        "bowtie" => ("⋈", sym(Rel)),
        "coloneqq" => ("≔", sym(Rel)),
        "triangleq" => ("≜", sym(Rel)),
        "to" | "rightarrow" => ("→", sym(Rel)),
        "gets" | "leftarrow" => ("←", sym(Rel)),
        "leftrightarrow" => ("↔", sym(Rel)),
        "Rightarrow" | "implies" => ("⇒", sym(Rel)),
        "Leftarrow" | "impliedby" => ("⇐", sym(Rel)),
        "Leftrightarrow" | "iff" => ("⇔", sym(Rel)),
        "longrightarrow" => ("⟶", sym(Rel)),
        "longleftarrow" => ("⟵", sym(Rel)),
        "longleftrightarrow" => ("⟷", sym(Rel)),
        "Longrightarrow" => ("⟹", sym(Rel)),
        "Longleftarrow" => ("⟸", sym(Rel)),
        "Longleftrightarrow" => ("⟺", sym(Rel)),
        "mapsto" => ("↦", sym(Rel)),
        "longmapsto" => ("⟼", sym(Rel)),
        "uparrow" => ("↑", sym(Rel)),
        "downarrow" => ("↓", sym(Rel)),
        "updownarrow" => ("↕", sym(Rel)),
        "Uparrow" => ("⇑", sym(Rel)),
        "Downarrow" => ("⇓", sym(Rel)),
        "nearrow" => ("↗", sym(Rel)),
        "searrow" => ("↘", sym(Rel)),
        "swarrow" => ("↙", sym(Rel)),
        "nwarrow" => ("↖", sym(Rel)),
        "hookrightarrow" => ("↪", sym(Rel)),
        "hookleftarrow" => ("↩", sym(Rel)),
        "rightharpoonup" => ("⇀", sym(Rel)),
        "leftharpoonup" => ("↼", sym(Rel)),
        "rightleftharpoons" => ("⇌", sym(Rel)),
        "therefore" => ("∴", sym(Rel)),
        "because" => ("∵", sym(Rel)),
        // 大运算符。
        "sum" => ("∑", Kind::BigOp(true)),
        "prod" => ("∏", Kind::BigOp(true)),
        "coprod" => ("∐", Kind::BigOp(true)),
        "bigcup" => ("⋃", Kind::BigOp(true)),
        "bigcap" => ("⋂", Kind::BigOp(true)),
        "bigvee" => ("⋁", Kind::BigOp(true)),
        "bigwedge" => ("⋀", Kind::BigOp(true)),
        "bigoplus" => ("⨁", Kind::BigOp(true)),
        "bigotimes" => ("⨂", Kind::BigOp(true)),
        "bigodot" => ("⨀", Kind::BigOp(true)),
        "biguplus" => ("⨄", Kind::BigOp(true)),
        "bigsqcup" => ("⨆", Kind::BigOp(true)),
        "int" => ("∫", Kind::BigOp(false)),
        "iint" => ("∬", Kind::BigOp(false)),
        "iiint" => ("∭", Kind::BigOp(false)),
        "oint" => ("∮", Kind::BigOp(false)),
        "oiint" => ("∯", Kind::BigOp(false)),
        // 函数名：正体；`\lim` 这类上下限在正下方。
        "lim" => ("lim", Kind::Func(true)),
        "limsup" => ("lim sup", Kind::Func(true)),
        "liminf" => ("lim inf", Kind::Func(true)),
        "max" => ("max", Kind::Func(true)),
        "min" => ("min", Kind::Func(true)),
        "sup" => ("sup", Kind::Func(true)),
        "inf" => ("inf", Kind::Func(true)),
        "det" => ("det", Kind::Func(true)),
        "gcd" => ("gcd", Kind::Func(true)),
        "Pr" => ("Pr", Kind::Func(true)),
        "argmax" => ("arg max", Kind::Func(true)),
        "argmin" => ("arg min", Kind::Func(true)),
        "sin" => ("sin", Kind::Func(false)),
        "cos" => ("cos", Kind::Func(false)),
        "tan" => ("tan", Kind::Func(false)),
        "cot" => ("cot", Kind::Func(false)),
        "sec" => ("sec", Kind::Func(false)),
        "csc" => ("csc", Kind::Func(false)),
        "sinh" => ("sinh", Kind::Func(false)),
        "cosh" => ("cosh", Kind::Func(false)),
        "tanh" => ("tanh", Kind::Func(false)),
        "coth" => ("coth", Kind::Func(false)),
        "arcsin" => ("arcsin", Kind::Func(false)),
        "arccos" => ("arccos", Kind::Func(false)),
        "arctan" => ("arctan", Kind::Func(false)),
        "log" => ("log", Kind::Func(false)),
        "ln" => ("ln", Kind::Func(false)),
        "lg" => ("lg", Kind::Func(false)),
        "exp" => ("exp", Kind::Func(false)),
        "arg" => ("arg", Kind::Func(false)),
        "deg" => ("deg", Kind::Func(false)),
        "dim" => ("dim", Kind::Func(false)),
        "ker" => ("ker", Kind::Func(false)),
        "hom" => ("hom", Kind::Func(false)),
        "mod" | "bmod" => ("mod", Kind::Func(false)),
        _ => return None,
    };
    Some(found)
}
